import urllib.request, html.parser
from pathlib import Path
class Reader(html.parser.HTMLParser):
 def __init__(self): super().__init__(); self.data=[]
 def handle_data(self,d):
  if d.strip(): self.data.append(d.strip())
pages={'wc':'https://brainx.chaobrain.com/brainmass/reference/generated/brainmass.WilsonCowanStep.html','pac':'https://brainx.chaobrain.com/braintools/apis/generated/braintools.metric.phase_amplitude_coupling.html','psd':'https://brainx.chaobrain.com/braintools/apis/generated/braintools.metric.power_spectral_density.html'}
out=Path('/workspace/theta_gamma/docs'); out.mkdir(exist_ok=True)
for key,url in pages.items():
 try:
  raw=urllib.request.urlopen(url, timeout=30).read().decode(); p=Reader(); p.feed(raw); txt=' '.join(p.data)
  (out/(key+'.txt')).write_text(url+'\\n'+txt)
  start=txt.find('class brainmass.') if key=='wc' else txt.find('braintools.metric.'+('phase_amplitude_coupling' if key=='pac' else 'power_spectral_density')+' (')
  print(key,txt[max(0,start):max(0,start)+24000])
 except Exception as e: print(key,type(e).__name__,str(e))
PY"

